<?php\n\nnamespace App\\Notifications;\n\nuse Illuminate\\Bus\\Queueable;\nuse Illuminate\\Contracts\\Queue\\ShouldQueue;\nuse Illuminate\\Notifications\\Messages\\MailMessage;\nuse Illuminate\\Notifications\\Notification;\n\nclass LowStockAlert extends Notification\n{\n    use Queueable;\n\n    protected $lowStockMaterials;\n\n    public function __construct($lowStockMaterials)\n    {\n        $this->lowStockMaterials = $lowStockMaterials;\n    }\n\n    public function via($notifiable)\n    {\n        return ['database', 'mail'];\n    }\n\n    public function toMail($notifiable)\n    {\n        $message = (new MailMessage)\n            ->subject('Low Stock Alert - Monitorbizz')\n            ->greeting('Hello ' . $notifiable->name)\n            ->line('The following materials are running low on stock:');\n            \n        foreach ($this->lowStockMaterials as $item) {\n            $message->line('• ' . $item['material']->name . ': ' . $item['current_stock'] . ' units remaining (Reorder at: ' . $item['reorder_point'] . ')');\n        }\n        \n        $message->action('View Inventory', url('/inventory'))\n                ->line('Please consider creating purchase orders for these materials.');\n                \n        return $message;\n    }\n\n    public function toArray($notifiable)\n    {\n        return [\n            'type' => 'low_stock_alert',\n            'title' => 'Low Stock Alert',\n            'message' => count($this->lowStockMaterials) . ' materials are running low on stock',\n            'materials' => collect($this->lowStockMaterials)->map(function($item) {\n                return [\n                    'name' => $item['material']->name,\n                    'current_stock' => $item['current_stock'],\n                    'reorder_point' => $item['reorder_point']\n                ];\n            })->toArray(),\n            'url' => url('/inventory')\n        ];\n    }\n}